#[cfg(feature = "git")]
pub(super) fn pending_behavior(slug: &str, context: &str) {
    assert!(
        PENDING_BEHAVIORS
            .iter()
            .any(|p| p.marker.strip_prefix("PENDING_DECISION:") == Some(slug)),
        "unregistered design difference {slug}: {context}"
    );
}
